const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const icon=(name)=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
// The shelf (stages, variety cards, filters, search, product sheet) lives in shelf.js; content in catalog.js.
const currency=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
let cart=read('mm-cart',[]).filter(x=>x&&typeof x.sku==='string'&&STAGES.some(p=>p.apiStage===x.stage)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=20).map(x=>({sku:x.sku,stage:x.stage,qty:x.qty,weight:Number(x.weight)||0})),favorites=read('mm-favorites',[]),filter='all',lastFocus=null;
// API data: skus from GET /v1/products (rupees), stock[sku][stage] from GET /v1/catalogue once a pincode is known.
let skus=[],stock=null,policy=null,where=read('mm-where',{pincode:null,deliveryDate:null,deliveryDates:[],cutoffTime:null,serviceable:null});
const skuOf=sku=>skus.find(s=>s.sku===sku),kgOf=s=>parseFloat(s.boxSize)||0,priceOf=sku=>skuOf(sku)?.price??0;
const boxLabel=s=>`${s.variety} · ${String(s.boxSize).replace('kg',' kg')} box`;
const qtyOf=(sku,stage)=>stock?(stock[sku]?.[stage]??0):undefined;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
const wait=ms=>new Promise(r=>setTimeout(r,ms));
function applyCheck(pin,c){const keep=where.pincode===pin&&(c.deliveryDates||[]).includes(where.deliveryDate);where={pincode:pin,deliveryDate:keep?where.deliveryDate:(c.earliestDeliveryDate||(c.deliveryDates||[])[0]||null),deliveryDates:c.deliveryDates||[],cutoffTime:c.cutoffTime||null,serviceable:!!c.serviceable};save('mm-where',where)}
async function refreshWhere(){if(!where.pincode)return;const c=await MM.deliveryCheck(where.pincode);applyCheck(where.pincode,c);loadStock()}
async function loadStock(){if(!where.pincode||!where.serviceable)stock=null;else try{const c=await MM.catalogue(where.pincode,where.deliveryDate);if(!c.serviceable)stock=null;else{const next={};(c.items||[]).forEach(i=>{(next[i.sku]??={})[i.stage]=i.qty});stock=next}}catch{}renderProducts()}
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function toast(message){$('.toast').textContent=message;$('.toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),3000)}
function openDialog(id){$$('dialog[open]').forEach(d=>d.close());lastFocus=document.activeElement;const dialog=$(id);dialog.showModal();document.body.classList.add('locked');if(window.gsap&&!reduced)gsap.fromTo(dialog,{y:30,opacity:0,scale:.98},{y:0,opacity:1,scale:1,duration:.45,ease:'power3.out'})}
function closeDialogs(){const dialogs=$$('dialog[open]');dialogs.forEach(d=>d.close());document.body.classList.remove('locked');lastFocus?.focus()}
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{if(!$('dialog[open]'))document.body.classList.remove('locked')});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialogs()}})});
function totals(){return cart.reduce((t,x)=>{const s=skuOf(x.sku);t.kg+=(s?kgOf(s):x.weight||0)*x.qty;t.price+=(s?s.price:0)*x.qty;t.count+=x.qty;return t},{kg:0,price:0,count:0})}
function signedLine(){const p=window.MM&&MM.profile();return p?`<p class="cart-disclaimer">Signed in as ${esc(p.phone||p.name||'')} · <button class="text-button" data-orders style="display:inline-flex;max-width:none;padding:0">Your orders</button> · <button class="text-button" data-preorders style="display:inline-flex;max-width:none;padding:0">Pre-orders</button> · <button class="text-button" data-signout style="display:inline-flex;max-width:none;padding:0">Sign out</button></p>`:''}
function updateCart(){cart.forEach(x=>{const s=skuOf(x.sku);if(s)x.weight=kgOf(s)});save('mm-cart',cart);const t=totals();$$('.bag-count').forEach(el=>el.textContent=t.count);if(!cart.length){$('#cart-items').innerHTML=`<div class="empty-cart">${icon('bag')}<h3>Good things belong here.</h3><p>Your mango bag is waiting for a little sunshine.</p><button class="button primary" data-browse>Explore the mangoes ${icon('arrow')}</button></div>`;$('#cart-summary').innerHTML=signedLine();return}$('#cart-items').innerHTML=cart.map((x,i)=>{const p=stageOf(x.stage),s=skuOf(x.sku);return `<div class="cart-row">${thumb(x.sku,x.stage)}<div><h3>${esc(s?s.name:x.sku)}</h3><small>${p.stage}</small><div class="cart-row-bottom"><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="Remove one ${p.stage} box">−</button><span>${x.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Add one ${p.stage} box">+</button></div><strong>${currency((s?s.price:0)*x.qty)}</strong></div><button class="remove" data-remove="${i}">Remove</button></div></div>`}).join('');$('#cart-summary').innerHTML=`<div class="subtotal"><span>Subtotal <small>(${t.kg} kg)</small></span><strong>${currency(t.price)}</strong></div><p class="cart-disclaimer">Prices include GST. Delivery is free. Final availability is confirmed at checkout.</p>${t.kg>50?`<p class="prototype-tag">Your bag is over 50 kg. Get a tailored bulk quote.</p><button class="button primary full" data-bulk>Prepare a bulk enquiry ${icon('arrow')}</button>`:`<button class="button primary full" id="checkout">Checkout ${icon('arrow')}</button>`}${signedLine()}`;}
function formHeader(title){return `<div class="sheet-head"><h2>${title}</h2><button class="icon-button" data-close aria-label="Close form">${icon('close')}</button></div>`}
function bulkForm(){const kg=Math.max(51,totals().kg);$('#form-dialog').innerHTML=formHeader('A bigger kind of mango love.')+`<p>For orders above 50 kg. Tell us what you have in mind and prepare your enquiry.</p><div class="prototype-tag">Your enquiry is saved on this device. Send it on WhatsApp, or we'll see it in your help requests if you're signed in.</div><form id="bulk-form"><div class="form-grid"><label class="field">Your name<input name="name" autocomplete="name" required maxlength="100"></label><label class="field">Business / organisation<input name="business" autocomplete="organization" required maxlength="120"></label><label class="field">Email<input name="email" type="email" autocomplete="email" required></label><label class="field">Phone<input name="phone" type="tel" autocomplete="tel" required minlength="7" maxlength="20"></label><label class="field">Quantity (above 50 kg)<input name="quantity" type="number" min="51" max="100000" step="1" value="${kg}" required></label><label class="field">Preferred ripeness<select name="ripeness"><option>Raw</option><option>Semi-raw</option><option>Ripe</option><option>A mix</option></select></label><label class="field wide">Delivery city<input name="city" autocomplete="address-level2" required maxlength="100"></label><label class="field wide">Anything else?<textarea name="notes" rows="3" maxlength="1000" placeholder="Your preferred timing, packaging or requirements"></textarea></label></div><p class="form-footer">Pricing, harvest timing and delivery will need confirmation. Saving a draft does not place an order.</p><button class="button primary full" type="submit">Save enquiry draft ${icon('arrow')}</button></form>`;const draft=read('mm-bulk-draft',null);if(draft&&typeof draft==='object'){for(const [key,value] of Object.entries(draft)){const field=$('#bulk-form').elements.namedItem(key);if(field&&typeof value==='string')field.value=value}}openDialog('#form-dialog');}
// ---- Checkout: pincode → sign in → delivery (date, slot, address, quote) → pay → success. State in `co`, one sheet re-rendered per step.
const STATUS={PAYMENT_PENDING:'Awaiting payment',CONFIRMED:'Confirmed',PROCESSING:'Being packed',PACKED:'Packed',SHIPPED:'On its way',OUT_FOR_DELIVERY:'Out for delivery',DELIVERED:'Delivered',DELIVERY_FAILED:'Delivery missed',CANCELLED:'Cancelled',RTO:'Returned'};
