let co={},sheetSeq=0,authConfig=null;const scripts={};
// Checkout, orders and the profile draw on their own page (#page-body, pages.js); pre-orders and bulk in the form sheet. `view` is where the current flow draws.
let view='#form-dialog';const host=()=>$(view),onPage=()=>view==='#page-body';
const head=title=>onPage()?pageHead(title):formHeader(title);
function showHost(){if(!onPage()&&!$('#form-dialog').open)openDialog('#form-dialog')}
function loadScript(src){return scripts[src]??=new Promise((ok,no)=>{const s=document.createElement('script');s.src=src;s.async=true;s.onload=ok;s.onerror=()=>{delete scripts[src];no(new Error('load'))};document.head.appendChild(s)})}
const marker=seq=>`<i hidden data-co-root data-seq="${seq}"></i>`;
const alive=seq=>host()?.querySelector('[data-co-root]')?.dataset.seq===String(seq);
const fmtDate=d=>{if(!d)return '';const[y,m,day]=String(d).split('-').map(Number);return new Date(y,m-1,day).toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'})};
const fmtTime=t=>t?new Date(t).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'}):'';
const skuName=sku=>skuOf(sku)?.name||sku||'An item';
const normPhone=s=>String(s||'').replace(/\D/g,'').replace(/^(91|0)(?=\d{10}$)/,'');
const errorBox=()=>co.error?`<p class="prototype-tag" role="alert">${esc(co.error)}</p>`:'';
function otpError(e){return({OTP_INVALID:'That code isn’t right. Check it and try again.',OTP_EXPIRED:'That code has expired. Ask for a new one.',OTP_LOCKED:'Too many wrong tries. Ask for a new code.',OTP_LIMIT:'Too many codes for this number. Please try again later.',RATE_LIMITED:'Too many tries. Please wait a minute and try again.',CAPTCHA_REQUIRED:'Please complete the check above and try again.',CAPTCHA_FAILED:'Please complete the check above and try again.',OTP_NOT_SENT:'We couldn’t send the code. Try again, or use WhatsApp instead.'})[e.code]||e.message}
function orderError(e){const x=e.extra||{};return({STOCK_INSUFFICIENT:`Not enough ${skuName(x.sku)} left for this day. Lower the quantity or choose another date.`,PRODUCT_UNAVAILABLE:`${skuName(x.sku)} is no longer available. Remove it from your bag to continue.`,SLOT_REQUIRED:'Choose a delivery slot.',SLOT_FULL:'That slot just filled up. Choose another.',SLOT_INVALID:'Choose a delivery slot.',CART_EMPTY:'Your bag is empty.',NOT_SERVICEABLE:`We don't deliver to ${where.pincode} yet.`,INVALID_DATE:'That delivery date is no longer available. Choose another.',NO_DELIVERY_DAY:'We don’t deliver on that day. Choose another date.',DATE_CLOSED:'That delivery date has closed. Choose another.',DATE_FULL:'That delivery date is full. Choose another.',RATE_LIMITED:'Too many tries. Please wait a minute and try again.',PAYMENTS_UNAVAILABLE:'Payments are paused for a moment. Please try again shortly.',PAYMENT_GATEWAY_ERROR:'We couldn’t reach the payment service. Please try again.',HOLD_LIMIT:'That is more boxes than we can hold at once. For larger orders, use our bulk enquiry.',PAYMENT_STARTING:'Your payment is still starting. Please try again in a moment.'})[e.code]||e.message}
// Shared steps: pincode (when needPin) → sign in → then(). Checkout, pre-order and deep links use them.
function startSteps(title,needPin,then,kind){co={seq:++sheetSeq,kind,title,needPin,then,step:null,draft:{pincode:where.pincode||'',phone:'',address:'',name:MM.profile()?.name||''},error:'',busy:false,loading:false,slots:[],slotId:null,quote:null,unpaid:null,pay:null,resendAt:0,captcha:null,siteKey:null};host().innerHTML=head(title)+marker(co.seq);showHost();(authConfig??=MM.authConfig().catch(()=>{authConfig=null;return{}})).then(c=>{co.siteKey=c&&c.turnstileSiteKey||null;if(co.siteKey&&['phone','code'].includes(co.step))renderCo()});goNext()}
function checkout(){startSteps('Your summer, almost packed.',true,enterDelivery,'checkout')}
function keepDraft(){const f=host();if(!f)return;['pincode','phone','address','name'].forEach(n=>{const el=f.querySelector(`[name="co-${n}"]`);if(el)co.draft[n]=el.value})}
function goNext(){co.error='';if(co.needPin!==false&&(!where.pincode||!where.serviceable)){co.step='pincode';renderCo()}else if(!MM.profile()){co.step='phone';renderCo()}else(co.then||enterDelivery)()}
function renderCo(){if(!alive(co.seq))return;const d=co.draft,dis=co.busy||co.loading?'disabled':'';let body='';
if(co.step==='pincode')body=`<p>Where should we bring your mangoes?</p><form id="co-pincode"><button type="button" class="locate-button liquid" data-co="locate-pin" ${dis}>${icon('pin')}${co.locating?'Finding you…':'Use my current location'}</button><div class="form-grid"><label class="field wide">Or type your pincode<input name="co-pincode" inputmode="numeric" autocomplete="postal-code" maxlength="6" required value="${esc(d.pincode)}"></label></div>${errorBox()}<button class="button primary full" type="submit" ${dis}>Continue ${icon('arrow')}</button></form>`;
else if(co.step==='phone')body=`<p>Sign in with your mobile number. We’ll send you a 6-digit code.</p><form id="co-phone"><div class="form-grid"><label class="field wide">Mobile number (+91)<input name="co-phone" type="tel" inputmode="numeric" autocomplete="tel-national" maxlength="16" required value="${esc(d.phone)}"></label></div><div id="co-captcha"></div>${errorBox()}<button class="button primary full" type="submit" ${dis}>Send code ${icon('arrow')}</button></form>`;
else if(co.step==='code')body=`<p>Enter the code we sent to +91 ${esc(co.phone)}. <button class="text-button" data-co="phone" style="display:inline-flex;max-width:none;padding:0">Change</button></p>${co.devCode?`<div class="prototype-tag">Test mode: your code is <b>${esc(co.devCode)}</b></div>`:''}<form id="co-code"><div class="form-grid"><label class="field wide">6-digit code<input name="co-code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" required></label></div><div id="co-captcha"></div>${errorBox()}<button class="button primary full" type="submit" ${dis}>Verify and continue ${icon('arrow')}</button></form><p class="form-footer"><button class="text-button" data-co="resend" style="display:inline-flex;max-width:none" ${dis}>Send again</button> · <button class="text-button" data-co="whatsapp" style="display:inline-flex;max-width:none" ${dis}>Send on WhatsApp instead</button></p>`;
else if(co.step==='delivery'){const q=co.quote;body=`<p>Delivering to <strong>${esc(where.pincode)}</strong>. <button class="text-button" data-co="pincode" style="display:inline-flex;max-width:none;padding:0">Change</button></p><form id="co-delivery" novalidate><div class="field">Delivery date</div>${dateCards(dis)}<p class="form-footer">Order by ${esc(where.cutoffTime||policy?.cutoffTime||'18:00 IST')}.</p>${co.slots.length?`<div class="field">Delivery slot</div><div class="slot-cards">${co.slots.map(s=>{const off=s.available===false,on=s.id===co.slotId;return `<button type="button" class="slot-card" data-slot="${esc(s.id)}" aria-pressed="${on}" ${off||co.busy?'disabled':''}><strong>${esc(s.label)}</strong><small>${esc(s.startsAt)}–${esc(s.endsAt)}${off?' · Full':''}</small>${on?icon('check'):''}</button>`}).join('')}</div>`:''}${addressPicker(dis)}<div class="form-grid" style="margin-top:14px"><label class="field wide">Delivery address<textarea name="co-address" rows="3" maxlength="500" required autocomplete="street-address" placeholder="House, street, area, landmark">${esc(d.address)}</textarea></label><label class="field wide">Name (optional)<input name="co-name" maxlength="80" autocomplete="name" value="${esc(d.name)}"></label></div>${co.loading?'<p class="form-footer">Checking your bag…</p>':q?`${q.lines.map(l=>{const p=stageOf(l.stage);return `<div class="cart-row">${thumb(l.sku,l.stage,l.name)}<div><h3>${esc(l.name)}</h3><small>${p.stage} · ${l.qty} × ${currency(l.unitPrice)}</small><div class="cart-row-bottom"><span></span><strong>${currency(l.linePrice)}</strong></div></div></div>`}).join('')}<div class="subtotal"><span>Subtotal</span><strong>${currency(q.subtotal)}</strong></div>${q.discount?`<div class="subtotal"><span>Discount</span><strong>−${currency(q.discount)}</strong></div>`:''}<div class="subtotal"><span>Total</span><strong>${currency(q.total)}</strong></div><p class="cart-disclaimer">Prices include GST. Delivery is free.${q.slot?` Arriving ${fmtDate(q.deliveryDate)}, ${esc(q.slot.label)}.`:''}</p>`:''}${errorBox()}${co.unpaid?`<p class="prototype-tag">You already have an unpaid order ${esc(co.unpaid.number)}.</p><button type="button" class="button primary full" data-co="unpaid-pay" ${dis}>Pay for it ${icon('arrow')}</button><button type="button" class="text-button" data-co="unpaid-cancel" style="margin:15px auto 0" ${dis}>Cancel it and continue</button>`:`<button class="button primary full" type="submit" ${dis}>${co.busy?'Placing your order…':`Pay${q?' '+currency(q.total):''}`} ${icon('arrow')}</button>`}</form>`}
else if(co.step==='pay'){const p=co.pay;body=`<p>Order <strong>${esc(p.number)}</strong> · ${currency(p.total)}. Your mangoes are held until ${fmtTime(p.holdExpiresAt)}.</p>${errorBox()}${p.razorpayKeyId?`<button class="button primary full" data-co="razorpay" ${dis}>Pay ${currency(p.total)} ${icon('arrow')}</button>`:`<div class="prototype-tag">Test mode: no payment service is connected, so no money is taken.</div><button class="button primary full" data-co="demo-captured" ${dis}>Pay (test) ${icon('arrow')}</button><button class="text-button" data-co="demo-failed" style="margin:15px auto 0" ${dis}>Fail payment (test)</button>`}${co.busy?'<p class="form-footer">Confirming your payment…</p>':''}<button class="text-button" data-order="${esc(p.orderId)}" style="margin:15px auto 0">View order</button>`}
else if(co.step==='success'){const p=co.pay;body=`<div class="success">${icon('check')}<h2>Order ${esc(p.number)} confirmed.</h2><p>Arriving ${fmtDate(p.deliveryDate)}${p.slotLabel?' · '+esc(p.slotLabel):''}.<br>We'll send updates on WhatsApp.</p><button class="button primary" data-browse>Back to the mangoes ${icon('arrow')}</button><button class="text-button" data-order="${esc(p.orderId)}" style="margin:15px auto 0">Track my order</button></div>`}
else if(co.step==='pre-address')body=`<p>Delivering to <strong>${esc(where.pincode)}</strong>. <button class="text-button" data-co="pincode" style="display:inline-flex;max-width:none;padding:0">Change</button></p><form id="co-preorder"><div class="form-grid"><label class="field wide">Delivery address<textarea name="co-address" rows="3" maxlength="500" required autocomplete="street-address" placeholder="House, street, area, landmark">${esc(d.address)}</textarea></label><label class="field wide">Name (optional)<input name="co-name" maxlength="80" autocomplete="name" value="${esc(d.name)}"></label></div>${errorBox()}<button class="button primary full" type="submit" ${dis}>${co.busy?'Booking your pre-order…':'Book my pre-order'} ${icon('arrow')}</button></form>`;
else if(co.step==='empty')body=`<div class="success">${icon('bag')}<h2>Your bag is empty.</h2><p>Add a box or two and come back to check out.</p><button class="button primary" data-browse>Explore the mangoes ${icon('arrow')}</button></div>`;
else if(co.step==='pre-book')body=`<p>Booking your pre-order…</p>${errorBox()}`;
else if(co.step==='failed'){const p=co.pay;body=`<div class="success">${icon('close')}<h2>Payment didn't go through.</h2><p>Your order ${esc(p.number)} is held until ${fmtTime(p.holdExpiresAt)}.</p><button class="button primary" data-co="retry">Try again ${icon('arrow')}</button><button class="text-button" data-order="${esc(p.orderId)}" style="margin:15px auto 0">View order</button></div>`}
host().innerHTML=head(co.title||'Your summer, almost packed.')+marker(co.seq)+(onPage()?`${co.kind==='checkout'?coSteps():''}<div class="page-card co-card">${body}</div>`:body);if(co.siteKey&&$('#co-captcha'))mountCaptcha();if(co.step==='delivery')mountMap()}
function mountCaptcha(){const el=$('#co-captcha'),seq=co.seq;co.captcha=null;loadScript(TURNSTILE).then(()=>{if(!el.isConnected||!window.turnstile||!alive(seq))return;turnstile.render(el,{sitekey:co.siteKey,action:'otp',size:'flexible',callback:t=>{co.captcha=t},'expired-callback':()=>{co.captcha=null},'error-callback':()=>{co.captcha=null}})}).catch(()=>{})}
async function submitPincode(){const pin=co.draft.pincode.trim();if(!/^[1-9]\d{5}$/.test(pin)){co.error='Enter a 6-digit pincode.';renderCo();return}co.busy=true;co.error='';renderCo();try{const c=await MM.deliveryCheck(pin);if(!c.serviceable){co.error=`We don't deliver to ${pin} yet.`;return}applyCheck(pin,c);loadStock();co.busy=false;goNext()}catch(e){co.error=e.message}finally{co.busy=false;renderCo()}}
async function sendCode(channel){const phone=normPhone(co.step==='code'?co.phone:co.draft.phone);if(!/^[6-9]\d{9}$/.test(phone)){co.error='Enter a 10-digit Indian mobile number.';renderCo();return}if(co.step==='code'&&Date.now()<co.resendAt){co.error=`You can ask for a new code in ${Math.ceil((co.resendAt-Date.now())/1000)} s.`;renderCo();return}co.busy=true;co.error='';renderCo();try{const r=await MM.otpRequest(phone,channel,co.captcha||undefined);co.phone=phone;co.devCode=r&&r.devCode||null;co.step='code';co.resendAt=Date.now()+30000;if(channel)toast(channel==='whatsapp'?'Code sent on WhatsApp':'New code sent')}catch(e){co.error=otpError(e)}finally{co.busy=false;renderCo()}}
async function verifyCode(code){code=String(code||'').replace(/\D/g,'');if(code.length!==6){co.error='Enter the 6-digit code.';renderCo();return}co.busy=true;co.error='';renderCo();try{const p=await MM.otpVerify(co.phone,code);if(!co.draft.name&&p&&p.name)co.draft.name=p.name;co.busy=false;toast('You’re signed in');goNext()}catch(e){co.error=otpError(e)}finally{co.busy=false;renderCo()}}
async function syncCart(){const server=await MM.cart();const want=new Set(cart.map(x=>x.sku+'|'+x.stage));for(const l of server.lines||[])if(!want.has(l.sku+'|'+l.stage))await MM.setCartItem(l.sku,l.stage,0);for(const x of [...cart]){try{await MM.setCartItem(x.sku,x.stage,x.qty)}catch(e){if(e.code!=='INVALID_SKU'&&e.status!==404)throw e;cart=cart.filter(y=>y!==x);updateCart();toast(`${skuName(x.sku)} is no longer available and was removed from your bag.`)}}}
async function loadSlots(retry=true){try{const r=await MM.slots(where.pincode,where.deliveryDate);co.slots=r.slots||[];if(co.slotId&&!co.slots.some(s=>s.id===co.slotId&&s.available!==false))co.slotId=null}catch(e){if(retry&&['INVALID_DATE','NO_DELIVERY_DAY'].includes(e.code)){await refreshWhere();return loadSlots(false)}if(e.code==='NOT_SERVICEABLE'){where.serviceable=false;save('mm-where',where)}throw e}}
async function doQuote(){co.quote=null;try{co.quote=await MM.quote({pincode:where.pincode,deliveryDate:where.deliveryDate,slotId:co.slotId||undefined});co.error=''}catch(e){co.error=orderError(e);if(e.code==='SLOT_FULL'){co.slotId=null;await loadSlots().catch(()=>{})}else if(e.code==='NOT_SERVICEABLE'){where.serviceable=false;save('mm-where',where);co.step='pincode'}else if(['INVALID_DATE','NO_DELIVERY_DAY','DATE_CLOSED'].includes(e.code))await refreshWhere().catch(()=>{});else if(e.status===401)co.step='phone'}return co.quote}
async function quoteIfReady(){if(co.slots.length&&!co.slotId){co.quote=null;return}await doQuote()}
async function enterDelivery(){co.step='delivery';co.quote=null;co.unpaid=null;co.loading=true;renderCo();try{await syncCart();if(!cart.length){co.step='empty';return}const [,saved]=await Promise.all([loadSlots(),MM.profile()?MM.addresses().catch(()=>[]):[]]);co.saved=saved||[];if(!co.draft.address&&co.saved.length){const a=co.saved.find(x=>x.pincode===where.pincode);if(a){co.draft.address=addressText(a.address);co.addressTouched=true;co.geo=addressPin(a.address);if(!co.draft.name&&a.name)co.draft.name=a.name}}await quoteIfReady()}catch(e){if(e.status===401){co.step='phone';co.error='Please sign in again.'}else co.error=orderError(e)}finally{co.loading=false;renderCo()}}
async function pickSlot(id){co.slotId=id;co.error='';co.loading=true;renderCo();await doQuote();co.loading=false;renderCo()}
async function changeDate(value){where.deliveryDate=value;save('mm-where',where);co.slotId=null;co.quote=null;co.error='';co.loading=true;renderCo();loadStock();try{await loadSlots();await quoteIfReady()}catch(e){co.error=orderError(e)}finally{co.loading=false;renderCo()}}
async function pay(){if(co.busy||co.loading)return;keepDraft();const address=co.draft.address.trim(),name=co.draft.name.trim();if(co.slots.length&&!co.slotId){co.error='Choose a delivery slot.';renderCo();return}if(address.length<10){co.error='Enter your full delivery address (at least 10 characters).';renderCo();return}if(name.length>80){co.error='Please shorten the name to 80 characters.';renderCo();return}co.busy=true;co.error='';renderCo();let c=null;try{if(!co.quote||Date.parse(co.quote.expiresAt)-Date.now()<20000){if(!await doQuote())return}let requoted=false,starting=0;for(;;){try{c=await MM.confirm({quoteId:co.quote.quoteId,address:withPin(address),...(name?{name}:{})});break}catch(e){if(e.code==='PAYMENT_STARTING'&&starting<5){starting++;await wait(2000);continue}if(e.code==='QUOTE_EXPIRED'&&!requoted){requoted=true;const before=co.quote.total;if(!await doQuote())return;if(co.quote.total!==before){co.error=`The total is now ${currency(co.quote.total)}. Tap Pay to continue.`;return}continue}if(e.code==='UNPAID_ORDER_EXISTS'){co.unpaid=e.extra;return}if(e.code==='PHONE_REQUIRED'){co.step='phone';co.error='Please confirm your mobile number to continue.';return}if(e.code==='SLOT_FULL'||e.code==='SLOT_REQUIRED'){co.slotId=null;co.quote=null;await loadSlots().catch(()=>{})}if(e.status===401){co.step='phone';co.error='Please sign in again.';return}co.error=orderError(e);return}}}finally{co.busy=false;if(!c)renderCo()}const slot=co.quote.slot||co.slots.find(s=>s.id===c.slotId);co.pay={orderId:c.orderId,number:c.number,total:c.total,deliveryDate:c.deliveryDate,slotLabel:slot?slot.label:'',razorpayKeyId:c.razorpayKeyId,razorpayOrderId:c.razorpayOrderId,holdExpiresAt:c.holdExpiresAt};co.step='pay';renderCo();if(c.razorpayKeyId)razorpay()}
function payFromOrder(o){co={seq:++sheetSeq,step:'pay',draft:{pincode:'',phone:'',address:'',name:''},error:'',busy:false,loading:false,slots:[],quote:null,pay:{orderId:o.id,number:o.number,total:o.total,deliveryDate:o.deliveryDate,slotLabel:o.slot?o.slot.label:'',razorpayKeyId:o.razorpayKeyId,razorpayOrderId:o.razorpayOrderId,holdExpiresAt:o.holdExpiresAt}};host().innerHTML=head('Your summer, almost packed.')+marker(co.seq);showHost();renderCo();if(o.razorpayKeyId)razorpay()}
async function razorpay(){const p=co.pay,seq=co.seq;try{await loadScript(RAZORPAY)}catch{co.error='We couldn’t open the payment window. Check your connection and try again.';renderCo();return}if(!alive(seq))return;new window.Razorpay({key:p.razorpayKeyId,order_id:p.razorpayOrderId,amount:Math.round(p.total*100),currency:'INR',name:'Mango Mandi',description:'Order '+p.number,prefill:{contact:MM.profile()?.phone||''},timeout:Math.max(1,Math.floor((Date.parse(p.holdExpiresAt)-Date.now())/1000)),handler:async reply=>{co.busy=true;co.error='';renderCo();try{await MM.verifyPayment(p.orderId,reply)}catch{}await settle(p,seq)},modal:{ondismiss:()=>{if(alive(seq)){co.error=`Payment window closed. Your mangoes are held until ${fmtTime(p.holdExpiresAt)}.`;renderCo()}}}}).open()}
async function demoPay(outcome){const p=co.pay,seq=co.seq;co.busy=true;co.error='';renderCo();try{const r=await MM.demoPay(p.orderId,outcome);if(r&&r.result==='attempt_failed'){co.busy=false;co.error='Payment didn’t go through. Please try again.';renderCo();return}await settle(p,seq)}catch(e){co.busy=false;co.error=e.message;renderCo()}}
async function settle(p,seq){let s=null;for(let i=0;i<20;i++){try{s=await MM.paymentStatus(p.orderId)}catch{s=null}if(s&&s.status!=='INITIATED')break;await wait(1500)}co.busy=false;if(s&&s.status==='SUCCEEDED'){cart=[];updateCart();if(alive(seq)){co.step='success';renderCo()}}else if(s&&s.status==='FAILED'){if(alive(seq)){co.step='failed';renderCo()}}else if(alive(seq)){toast('We’re still confirming your payment.');go('/orders/'+encodeURIComponent(p.orderId))}}
async function coAction(action){if(action==='pincode'){co.step='pincode';co.error='';co.unpaid=null;renderCo()}else if(action==='phone'){co.step='phone';co.error='';renderCo()}else if(action==='resend')sendCode('sms');else if(action==='whatsapp')sendCode('whatsapp');else if(action==='razorpay')razorpay();else if(action==='demo-captured')demoPay('captured');else if(action==='demo-failed')demoPay('failed');else if(action==='retry'){co.step='pay';co.error='';renderCo()}else if(action==='locate-pin'){keepDraft();const g=await locate();if(g&&/^[1-9]\d{5}$/.test(g.pincode)){co.draft.pincode=g.pincode;if(!co.draft.address)co.draft.address=g.address;renderCo();submitPincode()}else{if(g)co.error='We found you, but not your pincode. Please type it.';renderCo()}}else if(action==='locate'){const g=await locate();if(!g){renderCo();return}co.addressTouched=false;window.MapPick?.moveTo(g.lat,g.lng,18,{pick:false,accuracy:g.accuracy&&g.accuracy<2000?g.accuracy:null});await mapPicked(g,true);toast(g.accuracy>150?'Your location is rough here. Drag the map so the pin sits on your door.':'Add your house or flat number to the address')}else if(action==='map-use'){if(co.mapOffer){setAddress(co.mapOffer.address);co.mapOffer=null;renderCo()}}else if(action==='unpaid-pay'){try{payFromOrder(await MM.order(co.unpaid.orderId))}catch(e){co.error=e.message;renderCo()}}else if(action==='unpaid-cancel'){let go=false;co.busy=true;renderCo();try{await MM.cancelOrder(co.unpaid.orderId);co.unpaid=null;await syncCart();go=!!await doQuote()}catch(e){co.error=orderError(e)}finally{co.busy=false;renderCo()}if(go)pay()}}
// Checkout fields write to co.draft as they are typed, so re-renders (and values set in code, like a saved
// address or the map's address) never fight over the textarea. Also keeps the saved-address highlight in step.
document.addEventListener('input',e=>{const t=e.target,n=t.name;if(!n||!n.startsWith('co-')||!co.draft||!host()?.contains(t))return;co.draft[n.slice(3)]=t.value;if(n==='co-address'){co.addressTouched=true;markSaved()}});
function markSaved(){const now=(co.draft.address||'').trim();$$('.address-card',host()).forEach(b=>{const a=(co.saved||[]).find(x=>x.id===b.dataset.savedAddress);b.setAttribute('aria-pressed',!!a&&addressText(a.address)===now&&a.pincode===where.pincode)})}
// The map pin travels with the address text (the API stores text only): "…, Bengaluru · Pin: 12.934510,77.627110".
// Riders and staff see exactly where the door is; saved addresses and the order page read it back.
const PIN_RE=/\s*·?\s*Pin:\s*(-?\d{1,2}\.\d+),\s*(-?\d{1,3}\.\d+)\s*$/;
const addressText=a=>String(a||'').replace(PIN_RE,'').trim();
const addressPin=a=>{const m=String(a||'').match(PIN_RE);return m?{lat:Number(m[1]),lng:Number(m[2])}:null};
const withPin=a=>co.geo?`${addressText(a)} · Pin: ${co.geo.lat.toFixed(6)},${co.geo.lng.toFixed(6)}`.slice(0,500):a;
function setAddress(text){co.draft.address=text;co.addressTouched=false;const ta=host()?.querySelector('[name="co-address"]');if(ta)ta.value=text;markSaved()}
function mountMap(){const slot=$('#co-map-slot',host());if(!slot||!window.MapPick)return;MapPick.mount(slot,{center:co.geo,pick:g=>mapPicked(g)}).then(()=>{if(!co.geo&&!co.mapCentered){co.mapCentered=true;centerOnPincode()}}).catch(()=>{})}
async function centerOnPincode(){try{const f=await MapPick.nominatim(`search?format=jsonv2&countrycodes=in&postalcode=${encodeURIComponent(where.pincode)}&limit=1`);if(f[0]&&!co.geo)MapPick.moveTo(Number(f[0].lat),Number(f[0].lon),15,{pick:false})}catch{}}
// A spot from the map or the device: remember it, fill the address unless the customer typed their own
// (then offer it), and follow its pincode.
async function mapPicked(g,render=false){co.geo={lat:g.lat,lng:g.lng};const typed=co.addressTouched&&(co.draft.address||'').trim();if(g.address&&!typed){setAddress(g.address);co.mapOffer=null}else co.mapOffer=g.address?{address:g.address}:null;if(/^[1-9]\d{5}$/.test(g.pincode||'')&&g.pincode!==where.pincode){await switchPincode(g.pincode);return}if(render||co.mapOffer)renderCo()}
// ---- Checkout page helpers: the step bar, date cards, saved addresses and "use my current location".
const CO_STEPS=[['Area',['pincode']],['Sign in',['phone','code']],['Delivery',['delivery','empty']],['Payment',['pay','failed']],['Done',['success']]];
function coSteps(){const at=CO_STEPS.findIndex(([,s])=>s.includes(co.step));return `<ol class="co-steps">${CO_STEPS.map(([label],i)=>`<li class="${i<at?'done':i===at?'current':''}"${i===at?' aria-current="step"':''}>${label}</li>`).join('')}</ol>`}
const istDay=(offset=0)=>new Date(Date.now()+330*60000+offset*86400000).toISOString().slice(0,10);
const dayName=x=>x===istDay()?'Today':x===istDay(1)?'Tomorrow':new Date(x+'T00:00:00').toLocaleDateString('en-IN',{weekday:'short'});
function dateCards(dis){return `<div class="date-cards" role="group" aria-label="Delivery date">${(where.deliveryDates||[]).map(x=>{const dt=new Date(x+'T00:00:00'),on=x===where.deliveryDate;return `<button type="button" class="date-card" data-date="${x}" aria-pressed="${on}" aria-label="${fmtDate(x)}" ${dis}><small>${dayName(x)}</small><strong>${dt.getDate()}</strong><small>${dt.toLocaleDateString('en-IN',{month:'short'})}</small></button>`}).join('')}</div>`}
function addressPicker(dis){const saved=co.saved||[],now=(co.draft.address||'').trim();return `<div class="address-tools">${saved.length?`<div class="field">Saved addresses</div><div class="address-cards">${saved.map(a=>`<button type="button" class="address-card" data-saved-address="${esc(a.id)}" aria-pressed="${now===addressText(a.address)&&a.pincode===where.pincode}" ${dis}><strong>${esc(a.name||'Saved address')}</strong><small>${esc(addressText(a.address))} · ${esc(a.pincode)}</small></button>`).join('')}</div>`:''}<div class="field">Pin your door on the map</div><button type="button" class="locate-button liquid" data-co="locate" ${dis}>${icon('pin')}${co.locating?'Finding you…':'Use my current location'}</button><div id="co-map-slot" class="map-slot"></div>${co.mapOffer?`<p class="map-offer">The pin is at <strong>${esc(co.mapOffer.address)}</strong>. <button type="button" class="text-button" data-co="map-use">Use this address</button></p>`:''}</div>`}
async function switchPincode(pin){co.error='';co.loading=true;renderCo();try{const c=await MM.deliveryCheck(pin);if(!c.serviceable){co.error=`We don't deliver to ${pin} yet.`;return}applyCheck(pin,c);loadStock();co.slotId=null;co.quote=null;await loadSlots();await quoteIfReady();toast(`Delivering to ${pin}`)}catch(e){co.error=orderError(e)}finally{co.loading=false;renderCo()}}
async function useSaved(id){const a=(co.saved||[]).find(x=>x.id===id);if(!a)return;co.draft.address=addressText(a.address);co.addressTouched=true;co.mapOffer=null;if(a.name)co.draft.name=a.name;const pin=addressPin(a.address);if(pin){co.geo=pin;window.MapPick?.moveTo(pin.lat,pin.lng,18,{pick:false})}if(a.pincode!==where.pincode)await switchPincode(a.pincode);else renderCo()}
// The browser's location, turned into an address and pincode by OpenStreetMap's Nominatim (the old Next shop did the same).
async function reverseGeocode(lat,lng){const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&addressdetails=1&zoom=18&lat=${lat.toFixed(6)}&lon=${lng.toFixed(6)}`,{headers:{'Accept-Language':'en-IN'}});if(!r.ok)throw new Error('lookup');const g=await r.json(),a=g.address||{};const parts=[a.building||a.amenity,[a.house_number,a.road].filter(Boolean).join(' '),a.neighbourhood||a.quarter,a.suburb,a.city_district,a.city||a.town||a.village||a.state_district].filter(Boolean);return{pincode:String(a.postcode||'').replace(/\s/g,''),address:[...new Set(parts)].join(', ')||g.display_name||''}}
async function locate(){if(!navigator.geolocation){co.error='This browser can’t share your location. Type your address instead.';return null}co.locating=true;co.error='';renderCo();try{const pos=await new Promise((ok,no)=>navigator.geolocation.getCurrentPosition(ok,no,{enableHighAccuracy:true,timeout:15000,maximumAge:60000}));const g=await reverseGeocode(pos.coords.latitude,pos.coords.longitude);return{...g,lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy}}catch(e){co.error=e&&e.code===1?'Location is turned off for this site. Allow it in your browser, or type your address.':'We couldn’t find your location. Type your address instead.';return null}finally{co.locating=false}}
// ---- Orders: list and detail, on the orders page (or the form sheet).
async function ordersView(){const seq=++sheetSeq;host().innerHTML=head('Your orders')+marker(seq)+'<p>Loading your orders…</p>';showHost();let body;try{const list=await MM.orders();body=list.length?list.map(o=>`<button class="guide-choice" data-order="${esc(o.id)}"><span class="dot ${o.status==='PAYMENT_PENDING'?'semi':['CANCELLED','RTO','DELIVERY_FAILED'].includes(o.status)?'raw':'ripe'}"></span><span><strong>${esc(o.number)} · ${STATUS[o.status]||esc(o.status)}</strong><small>Delivery ${fmtDate(o.deliveryDate)} · ${currency(o.total)}</small></span>${icon('arrow')}</button>`).join(''):'<p>No orders yet. Your first box of summer is a tap away.</p>'}catch(e){body=`<p class="prototype-tag" role="alert">${esc(e.status===401?'Please sign in again to see your orders.':e.message)}</p>`}if(alive(seq))host().innerHTML=head('Your orders')+marker(seq)+(onPage()?`<div class="page-card">${body}</div>`:body)}
async function orderView(id,quiet=false,seq=++sheetSeq){if(!quiet){host().innerHTML=head('Your order')+marker(seq)+'<p>Loading your order…</p>';showHost()}let o;try{o=await MM.order(id)}catch(e){if(alive(seq)&&!quiet)host().innerHTML=head('Your order')+marker(seq)+`<p class="prototype-tag" role="alert">${esc(e.message)}</p><button class="text-button" data-orders>All orders</button>`;if(quiet&&alive(seq))setTimeout(()=>alive(seq)&&orderView(id,true,seq),5000);return}if(!alive(seq))return;const left=o.holdExpiresAt?Date.parse(o.holdExpiresAt)-Date.now():0,canPay=o.status==='PAYMENT_PENDING'&&o.razorpayOrderId&&left>60000,canCancel=['PAYMENT_PENDING','CONFIRMED','PROCESSING'].includes(o.status);host().innerHTML=head(`Order ${esc(o.number)}`)+marker(seq)+(onPage()?'<div class="page-card">':'')+`<p>${STATUS[o.status]||esc(o.status)} · Delivery ${fmtDate(o.deliveryDate)}${o.slot?' · '+esc(o.slot.label):''}</p>${o.deliveryCode?`<div class="prototype-tag">Delivery code: <b>${esc(o.deliveryCode)}</b> · share it with your rider.</div>`:''}${(o.items||[]).map(l=>{const p=stageOf(l.stage);return `<div class="cart-row">${thumb(l.sku,l.stage,l.name)}<div><h3>${esc(l.name)}</h3><small>${p.stage} · ${l.quantity} × ${currency(l.unitPrice)}</small><div class="cart-row-bottom"><span></span><strong>${currency(l.linePrice)}</strong></div></div></div>`}).join('')}${o.discount?`<div class="subtotal"><span>Discount</span><strong>−${currency(o.discount)}</strong></div>`:''}<div class="subtotal"><span>Total</span><strong>${currency(o.total)}</strong></div><p class="cart-disclaimer">Delivering to ${esc(o.deliveryAddress)}${o.pincode?' · '+esc(o.pincode):''}</p>${(o.timeline||[]).length?`<p class="form-footer">${o.timeline.map(t=>`${STATUS[t.status]||esc(t.status)} · ${new Date(t.at).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})}`).join('<br>')}</p>`:''}${canPay?`<button class="button primary full" data-pay-order="${esc(o.id)}">Pay now ${currency(o.total)} ${icon('arrow')}</button>`:''}${canCancel?`<button class="text-button" data-cancel-order="${esc(o.id)}" data-number="${esc(o.number)}" style="margin:15px auto 0">Cancel order</button>`:''}<button class="text-button" data-orders style="margin:15px auto 0">All orders</button>`+(onPage()?'</div>':'');if(o.status==='PAYMENT_PENDING')setTimeout(()=>alive(seq)&&orderView(id,true,seq),5000)}
async function cancelOrder(id,number){if(!window.confirm(`Cancel order ${number}?`))return;try{await MM.cancelOrder(id);toast(`Order ${number} cancelled`)}catch(e){toast(e.code==='NOT_CANCELLABLE'?'This order can no longer be cancelled.':e.message)}if(pageOpen())route();else orderView(id)}
async function payOrder(id){try{payFromOrder(await MM.order(id))}catch(e){toast(e.message)}}
// ---- Pre-order: a separate paid booking (sku, stage, qty, week), paid by Razorpay payment link. Pincode and sign-in reuse the checkout steps.
const PRE_STATUS={PAYMENT_PENDING:'Awaiting payment',BOOKED:'Booked',WAITLISTED:'On the waitlist',CONVERTED:'Became order',CANCELLED:'Cancelled'};
let pre={weeks:[],stages:['RAW','SEMI_RIPE','RIPE'],cancelPolicy:'',sku:null,stage:'SEMI_RIPE',weekStart:null,qty:1,address:'',name:'',force:false,offer:false,unpaid:null,error:''};
const realUrl=u=>!!u&&!String(u).includes('plink_dev_');
const fmtWeek=d=>{if(!d)return '';const[y,m,day]=String(d).split('-').map(Number);return new Date(y,m-1,day).toLocaleDateString('en-IN',{day:'numeric',month:'short'})};
const preWeek=()=>pre.weeks.find(x=>x.sku===pre.sku&&x.weekStart===pre.weekStart);
const preTotal=()=>{const w=preWeek();return w?`<span>Total <small>(${pre.qty} × ${currency(w.price)})</small></span><strong>${currency(pre.qty*w.price)}</strong>`:''};
function preFix(){const boxes=[...new Set(pre.weeks.map(x=>x.sku))];if(!boxes.includes(pre.sku))pre.sku=boxes[0]||null;const mine=pre.weeks.filter(x=>x.sku===pre.sku);if(!mine.some(x=>x.weekStart===pre.weekStart))pre.weekStart=(mine.find(x=>x.remaining>0)||mine[0]||{}).weekStart||null;if(!pre.stages.includes(pre.stage))pre.stage=pre.stages.includes('SEMI_RIPE')?'SEMI_RIPE':pre.stages[0];const w=preWeek(),max=Math.min(20,w&&w.remaining>0?w.remaining:20);pre.qty=Math.min(max,Math.max(1,Math.floor(Number(pre.qty))||1));return max}
async function loadWeeks(){const r=await MM.preorderWeeks();pre.weeks=r.weeks||[];pre.stages=(r.stages||[]).length?r.stages:['RAW','SEMI_RIPE','RIPE'];pre.cancelPolicy=r.cancelPolicy||'';preFix()}
function preError(e){return({PREORDER_FULL:'That week just filled up. Join the waitlist for the next free spot, or choose another week.',INVALID_WEEK:'That week is no longer open for pre-orders. Choose another.',UNPAID_PREORDER_EXISTS:'',PHONE_REQUIRED:'Please confirm your mobile number to continue.'})[e.code]??orderError(e)}
async function preorderForm(){view='#form-dialog';const seq=++sheetSeq;pre.error='';pre.offer=false;pre.unpaid=null;$('#form-dialog').innerHTML=formHeader('Save your first taste.')+marker(seq)+'<p>Plan your box ahead of the season. Harvest dates and delivery availability will be announced.</p>';openDialog('#form-dialog');try{await loadWeeks()}catch(e){pre.weeks=[];pre.error=e.message}if(alive(seq))renderPreorder(seq)}
function renderPreorder(seq=++sheetSeq){const head=formHeader('Save your first taste.')+marker(seq),alert=pre.error?`<p class="prototype-tag" role="alert">${esc(pre.error)}</p>`:'';if(!pre.weeks.length){$('#form-dialog').innerHTML=head+`<p>Plan your box ahead of the season. Harvest dates and delivery availability will be announced.</p>${alert||'<p class="form-footer">Pre-orders open soon. Check back before the season.</p>'}<button class="button primary full" data-close>Back to the mangoes ${icon('arrow')}</button>`;return}const max=preFix(),boxes=[...new Map(pre.weeks.map(x=>[x.sku,x])).values()],policy=String(pre.cancelPolicy||'Cancel any time before packing for a full refund.').trim().replace(/\.$/,'');$('#form-dialog').innerHTML=head+`<p>Plan your box ahead of the season.</p><div class="prototype-tag">Paid in full now by Razorpay · ${esc(policy.charAt(0).toLowerCase()+policy.slice(1))}</div><form id="preorder-form"><div class="form-grid"><label class="field">Your mango moment<select name="stage">${pre.stages.map(s=>`<option value="${esc(s)}" ${s===pre.stage?'selected':''}>${stageOf(s).stage}</option>`).join('')}</select></label><label class="field">Box<select name="sku">${boxes.map(s=>`<option value="${esc(s.sku)}" ${s.sku===pre.sku?'selected':''}>${esc(boxLabel(s))} · ${currency(s.price)}</option>`).join('')}</select></label><label class="field">Week<select name="week">${pre.weeks.filter(x=>x.sku===pre.sku).map(x=>`<option value="${esc(x.weekStart)}" ${x.weekStart===pre.weekStart?'selected':''}>Week of ${fmtWeek(x.weekStart)}${x.remaining<=0?' · waitlist':''}</option>`).join('')}</select></label><label class="field">Boxes<input name="qty" type="number" inputmode="numeric" min="1" max="${max}" step="1" value="${pre.qty}" required></label></div><div class="subtotal" id="pre-total">${preTotal()}</div>${alert}${pre.unpaid?`<p class="prototype-tag">You already have an unpaid pre-order ${esc(pre.unpaid.number)}.</p><button type="button" class="button primary full" data-pre="unpaid-pay">Pay for it ${icon('arrow')}</button><button type="button" class="text-button" data-pre="unpaid-cancel" style="margin:15px auto 0">Cancel it and continue</button>`:pre.offer?`<button type="button" class="button primary full" data-pre="waitlist">Join the waitlist ${icon('arrow')}</button>`:`<button class="button primary full" type="submit">Book my pre-order ${icon('arrow')}</button>`}</form>`}
function preRead(f){const el=f.elements;pre.stage=el.namedItem('stage').value;pre.sku=el.namedItem('sku').value;pre.weekStart=el.namedItem('week').value;pre.qty=Number(el.namedItem('qty').value)}
function preQty(f){preRead(f);preFix();f.elements.namedItem('qty').value=pre.qty;$('#pre-total').innerHTML=preTotal()}
function preSubmit(force=false){pre.force=force;pre.error='';pre.offer=false;startSteps('Save your first taste.',true,preAddress)}
function preAddress(){if(pre.address){bookPre();return}co.step='pre-address';if(!co.draft.name)co.draft.name=pre.name||MM.profile()?.name||'';renderCo()}
function submitPreAddress(){const address=co.draft.address.trim(),name=co.draft.name.trim();if(address.length<10){co.error='Enter your full delivery address (at least 10 characters).';renderCo();return}if(address.length>500){co.error='Please shorten the address to 500 characters.';renderCo();return}if(name.length>80){co.error='Please shorten the name to 80 characters.';renderCo();return}pre.address=address;pre.name=name;bookPre()}
async function bookPre(){const w=preWeek(),seq=co.seq;if(!w){pre.error='Choose a week.';renderPreorder();return}if(co.step!=='pre-address')co.step='pre-book';co.busy=true;co.error='';renderCo();let r;try{r=await MM.bookPreorder({sku:pre.sku,stage:pre.stage,qty:pre.qty,weekStart:pre.weekStart,pincode:where.pincode,address:pre.address,...(pre.name?{name:pre.name}:{}),waitlist:pre.force||w.remaining<=0})}catch(e){co.busy=false;if(alive(seq))preFailed(e);return}co.busy=false;pre.force=false;pre.unpaid=null;if(realUrl(r.paymentUrl))window.location.assign(r.paymentUrl);else if(alive(seq))preorderView(r.id)}
async function preFailed(e){const seq=co.seq;if(e.status===401){co.step='phone';co.error='Please sign in again.';renderCo();return}if(e.code==='VALIDATION_ERROR'){pre.address='';co.step='pre-address';co.error=e.message;renderCo();return}if(e.code==='NOT_SERVICEABLE'){where.serviceable=false;save('mm-where',where)}pre.unpaid=e.code==='UNPAID_PREORDER_EXISTS'?e.extra:null;pre.offer=e.code==='PREORDER_FULL';pre.error=preError(e);if(['PREORDER_FULL','INVALID_WEEK'].includes(e.code))await loadWeeks().catch(()=>{});if(alive(seq))renderPreorder()}
async function preAction(action,id,number){if(action==='waitlist')preSubmit(true);else if(action==='view')preorderView(id);else if(action==='cancel')cancelPre(id,number);else if(action==='pay-test')devPayPre(id,'captured');else if(action==='fail-test')devPayPre(id,'failed');else if(action==='unpaid-pay')preorderView(pre.unpaid.preorderId);else if(action==='unpaid-cancel'){$$('#form-dialog [data-pre]').forEach(b=>b.disabled=true);try{await MM.cancelPreorder(pre.unpaid.preorderId);toast(`Pre-order ${pre.unpaid.number} cancelled`);pre.unpaid=null;preSubmit(pre.force)}catch(e){pre.error=e.message;renderPreorder()}}}
async function devPayPre(id,outcome){const seq=sheetSeq;$$('#form-dialog [data-pre]').forEach(b=>b.disabled=true);try{const r=await MM.api('/'+['dev','pay-preorder'].join('/'),{method:'POST',body:{preorderId:id,outcome}});if(outcome==='failed'||(r&&r.result==='ignored'))toast('Payment didn’t go through. Please try again.')}catch(e){toast(e.message)}if(alive(seq))preorderView(id,true,seq,10)}
async function preorderView(id,quiet=false,seq=++sheetSeq,polls=0){if(quiet&&view!=='#form-dialog')return;view='#form-dialog';const head=formHeader('Your pre-order')+marker(seq);if(!quiet){$('#form-dialog').innerHTML=head+'<p>Loading your pre-order…</p>';if(!$('#form-dialog').open)openDialog('#form-dialog')}let p;try{p=await MM.preorder(id)}catch(e){if(alive(seq)&&!quiet)$('#form-dialog').innerHTML=head+`<p class="prototype-tag" role="alert">${esc(e.status===401?'Please sign in again to see your pre-order.':e.message)}</p><button class="text-button" data-preorders style="margin:15px auto 0">All pre-orders</button>`;if(quiet&&polls>0&&alive(seq))setTimeout(()=>alive(seq)&&preorderView(id,true,seq,polls-1),2000);return}if(!alive(seq))return;const pending=p.status==='PAYMENT_PENDING';$('#form-dialog').innerHTML=head+`<div class="success">${icon(p.status==='CANCELLED'?'close':'check')}<h2>Pre-order ${esc(p.number)}</h2><p><strong>${PRE_STATUS[p.status]||esc(p.status)}</strong>${p.status==='CONVERTED'&&p.orderId?` · <button class="text-button" data-order="${esc(p.orderId)}" style="display:inline-flex;max-width:none;padding:0">View order</button>`:''}<br>${esc(p.productName)} · ${stageOf(p.stage).stage} · ${p.qty} ${p.qty===1?'box':'boxes'}<br>Week of ${fmtWeek(p.weekStart)} · ${currency(p.total)}<br>Delivering to ${esc(p.address)}${p.pincode?' · '+esc(p.pincode):''}</p>${pending?(realUrl(p.paymentUrl)?`<a class="button primary" href="${esc(p.paymentUrl)}">Pay now ${currency(p.total)} ${icon('arrow')}</a>`:`<div class="prototype-tag">Test mode: no payment service is connected, so no money is taken.</div><button class="button primary" data-pre="pay-test" data-id="${esc(p.id)}">Pay (test) ${icon('arrow')}</button><button class="text-button" data-pre="fail-test" data-id="${esc(p.id)}" style="margin:15px auto 0">Fail payment (test)</button>`):`<button class="button primary" data-close>Back to the mangoes ${icon('arrow')}</button>`}${['CANCELLED','CONVERTED'].includes(p.status)?'':`<button class="text-button" data-pre="cancel" data-id="${esc(p.id)}" data-number="${esc(p.number)}" style="margin:15px auto 0">Cancel pre-order</button>`}${pending?`<button class="text-button" data-close style="margin:15px auto 0">Back to the mangoes</button>`:''}<button class="text-button" data-preorders style="margin:15px auto 0">All pre-orders</button></div>`;if(pending&&polls>0)setTimeout(()=>alive(seq)&&preorderView(id,true,seq,polls-1),2000)}
async function preordersView(){view='#form-dialog';const seq=++sheetSeq,head=formHeader('Your pre-orders')+marker(seq);$('#form-dialog').innerHTML=head+'<p>Loading your pre-orders…</p>';if(!$('#form-dialog').open)openDialog('#form-dialog');let body;try{const list=await MM.preorders();body=list.length?list.map(p=>`<button class="guide-choice" data-pre="view" data-id="${esc(p.id)}"><span class="dot ${['PAYMENT_PENDING','WAITLISTED'].includes(p.status)?'semi':p.status==='CANCELLED'?'raw':'ripe'}"></span><span><strong>${esc(p.number)} · ${PRE_STATUS[p.status]||esc(p.status)}</strong><small>Week of ${fmtWeek(p.weekStart)} · ${currency(p.total)}</small></span>${icon('arrow')}</button>`).join(''):'<p>No pre-orders yet. Plan your first taste of the season.</p>'}catch(e){body=`<p class="prototype-tag" role="alert">${esc(e.status===401?'Please sign in again to see your pre-orders.':e.message)}</p>`}if(alive(seq))$('#form-dialog').innerHTML=head+body}
async function cancelPre(id,number){if(!window.confirm(`Cancel pre-order ${number}?`))return;try{await MM.cancelPreorder(id);toast(`Pre-order ${number} cancelled`)}catch(e){toast(e.message)}preorderView(id)}
// ---- Deep links: /preorders/<id> (Razorpay returns here), /order/<id>, /orders/<id>. The address bar goes back to / so anchors stay on this page.
function openDeepLink(){const m=location.pathname.match(/^\/preorders\/([^/]+)\/?$/);if(m){history.replaceState(null,'','/'+location.hash);const id=decodeURIComponent(m[1]),open=()=>preorderView(id,false,++sheetSeq,10);MM.restore().then(()=>{if(MM.profile())open();else{view='#form-dialog';startSteps('Your pre-order',false,open)}});return}if(isPage(location.pathname))route();else if(location.pathname!=='/'&&location.pathname!=='/index.html')history.replaceState(null,'','/'+location.hash)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close')){if(b.closest('#page-view'))go('/');else closeDialogs()}else if(b.hasAttribute('data-cart')){updateCart();openDialog('#cart-dialog')}else if(b.hasAttribute('data-bulk'))bulkForm();else if(b.hasAttribute('data-preorder'))preorderForm();else if(b.hasAttribute('data-qty')){const i=Number(b.dataset.qty);cart[i].qty+=Number(b.dataset.delta);if(cart[i].qty<=0)cart.splice(i,1);else if(cart[i].qty>20){cart[i].qty=20;toast('Use bulk enquiries for larger quantities.')}updateCart()}else if(b.hasAttribute('data-remove')){cart.splice(Number(b.dataset.remove),1);updateCart()}else if(b.hasAttribute('data-browse')){closeDialogs();if(pageOpen())go('/#shop');else location.hash='shop'}else if(b.id==='guide-button')openDialog('#guide-dialog');else if(b.id==='checkout'){closeDialogs();go('/checkout')}else if(b.hasAttribute('data-orders')){closeDialogs();go('/orders')}else if(b.hasAttribute('data-preorders'))preordersView();else if(b.dataset.pre)preAction(b.dataset.pre,b.dataset.id,b.dataset.number);else if(b.hasAttribute('data-signout'))MM.signOut().then(()=>{updateCart();toast('Signed out');if(pageOpen())go('/')});else if(b.dataset.order){closeDialogs();go('/orders/'+encodeURIComponent(b.dataset.order))}else if(b.dataset.payOrder)payOrder(b.dataset.payOrder);else if(b.dataset.cancelOrder)cancelOrder(b.dataset.cancelOrder,b.dataset.number);else if(b.dataset.slot)pickSlot(b.dataset.slot);else if(b.dataset.date){if(b.dataset.date!==where.deliveryDate)changeDate(b.dataset.date)}else if(b.dataset.savedAddress)useSaved(b.dataset.savedAddress);else if(b.dataset.co)coAction(b.dataset.co)});
document.addEventListener('change',e=>{if(e.target.id==='co-date')changeDate(e.target.value);if(e.target.form&&e.target.form.id==='preorder-form'){if(e.target.name==='qty')preQty(e.target.form);else{preRead(e.target.form);pre.offer=false;pre.error='';renderPreorder()}}});
document.addEventListener('submit',e=>{if(['co-pincode','co-phone','co-code','co-delivery','co-preorder'].includes(e.target.id)){e.preventDefault();keepDraft();if(e.target.id==='co-pincode')submitPincode();else if(e.target.id==='co-phone')sendCode();else if(e.target.id==='co-code')verifyCode(e.target.elements.namedItem('co-code').value);else if(e.target.id==='co-preorder')submitPreAddress();else pay();return}if(e.target.id==='preorder-form'){e.preventDefault();preRead(e.target);preFix();preSubmit()}if(e.target.id==='bulk-form'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(Number(data.quantity)<=50)return;const stored=save('mm-bulk-draft',data),lines=Object.entries(data).map(([k,v])=>`${k}: ${v}`),wa=String((window.MM_CONFIG||{}).supportWhatsapp||'').trim(),waOk=/^\d+$/.test(wa);$('#form-dialog').innerHTML=formHeader('Your enquiry draft')+`<div class="success">${icon('check')}<h2>${stored?'Ready when you are.':'Your details are ready.'}</h2><p>${stored?'Your '+Number(data.quantity)+' kg enquiry has been saved on this device.':'Device storage is unavailable. Please download your draft to keep it.'}<br><span id="bulk-sent">${waOk?'Send it to us on WhatsApp, and download a copy to keep your requirements together.':'It has not been sent. Download a copy to keep your requirements together.'}</span></p>${waOk?`<a class="button primary" href="https://wa.me/${wa}?text=${encodeURIComponent(['Mango Mandi — Bulk enquiry',...lines].join('\n'))}" target="_blank" rel="noopener">Send on WhatsApp ${icon('arrow')}</a>`:''}<button class="button primary" id="download-draft">Download enquiry draft ${icon('arrow')}</button><button class="text-button" data-close style="margin:15px auto 0">Back to the mangoes</button></div>`;$('#download-draft').onclick=()=>{const text=['Mango Mandi — Bulk enquiry draft (not sent)',...lines].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download='mango-mandi-enquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};if(MM.profile())MM.helpInfo().then(()=>MM.helpRequest({topic:'OTHER',orderId:null,message:('Bulk enquiry: '+lines.join('; ')).slice(0,2000)})).then(r=>{const el=$('#bulk-sent');if(el&&r&&r.number)el.textContent=`Also sent to Mango Mandi as help request ${r.number}. Download a copy to keep your requirements together.`}).catch(()=>{})}});
$('#search').addEventListener('input',()=>{renderProducts()});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}});
window.addEventListener('resize',()=>positionPill(false));$('#year').textContent=new Date().getFullYear();window.addEventListener('mm:profile',()=>updateCart());renderOccasions();renderProducts();updateCart();positionPill(false);MM.restore();loadProducts();MM.policy().then(p=>{policy=p}).catch(()=>{});if(where.pincode&&where.serviceable)refreshWhere().catch(()=>loadStock());document.fonts.ready.then(()=>positionPill(false));openDeepLink();
if(window.gsap&&!reduced){gsap.registerPlugin(ScrollTrigger);gsap.from('.hero-copy > *',{y:22,opacity:0,duration:.9,stagger:.08,ease:'power3.out',delay:.1});gsap.from('.hero-photo img',{scale:1.08,duration:1.7,ease:'power2.out'});gsap.to('.hero-photo img',{yPercent:7,ease:'none',scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:1}});$$('.season,.story-title,.bulk').forEach(el=>gsap.from(el,{y:30,opacity:.35,duration:.9,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 92%',once:true}}));gsap.from('.story-values article',{y:20,opacity:.4,stagger:.15,duration:.8,scrollTrigger:{trigger:'.story-values',start:'top 90%',once:true}});}
const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){$$('.mobile-dock a').forEach(a=>a.classList.toggle('dock-active',a.hash==='#'+entry.target.id))}})},{rootMargin:'-15% 0px -60% 0px'});$$('#home,#shop,#preorder,#bulk').forEach(s=>observer.observe(s));
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
